export const BANCO_PART_1 = [
  { id: "N001", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Don Álvaro lleva 22 años con su pescadería en la ribera del Magdalena. Sus clientes de siempre envejecen y los jóvenes del barrio piden pollo por app. Cree que su único problema son las otras pescaderías del puerto.", pregunta: "¿Cuál diagnóstico es más preciso desde el mapeo de mercado?", opciones: ["El análisis debe incluir competidores sustitutos que compiten por el mismo presupuesto de proteína.", "La competencia directa entre pescaderías explica la caída y basta reducir precios.", "La caída obedece a causas externas fuera del control del negocio y no hay estrategia posible.", "El problema es generacional y ningún cambio comercial puede revertir la tendencia."], correcta: 0, justificacion: "El mapeo incluye competidores directos y sustitutos indirectos. Pollo y apps satisfacen la misma necesidad (proteína) y compiten por el mismo presupuesto." },
  { id: "N002", modulo: 1, tipoPregunta: "Verdadero / Falso", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un consultor afirma que el mapeo de mercado y la investigación de mercado son sinónimos y pueden usarse indistintamente en cualquier proyecto comercial.", pregunta: "¿Verdadero o falso?", opciones: ["Verdadero: son sinónimos exactos y cualquier uso es correcto.", "Falso: el mapeo dibuja el ecosistema completo; la investigación profundiza un problema específico.", "Verdadero: ambos producen información cuantificable para decisiones comerciales.", "Falso: solo la investigación de mercado es una herramienta profesional."], correcta: 1, justificacion: "El mapeo dibuja la estructura del mercado (actores, canales, precios); la investigación mide o comprende variables específicas. Son complementarios, no sinónimos." },
  { id: "N003", modulo: 1, tipoPregunta: "Completación de Enunciado", nivel: "Aplicación", rap: "RAP 1.1", contexto: "El proceso de identificar y describir todos los actores, canales, precios y flujos de un mercado se denomina __________. Su propósito es producir una representación __________ que permita decisiones basadas en evidencia.", pregunta: "¿Cuál opción completa correctamente ambos espacios?", opciones: ["Investigación de mercados / cuantitativa.", "Benchmarking / comparativa internacional.", "Mapeo de mercado / analítica y visual.", "Segmentación / demográfica."], correcta: 2, justificacion: "El mapeo de mercado produce una representación analítica y visual del ecosistema comercial para fundamentar decisiones con evidencia." },
  { id: "N004", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Una estudiante afirma: 'El mapeo de mercado sirve solo para grandes empresas, no para micronegocios de barrio'. Un tendero la escucha y duda de su valor.", pregunta: "¿Cuál es la refutación más sólida a esta afirmación?", opciones: ["El mapeo es exclusivo de multinacionales con presupuesto de consultoría.", "El mapeo requiere software especializado y no puede hacerse manualmente.", "El mapeo solo tiene valor si lo firma un consultor certificado.", "El mapeo es una metodología aplicable con recursos mínimos (cuaderno, observación) y es crítico para micronegocios sin margen de error estratégico."], correcta: 3, justificacion: "El mapeo es metodología, no herramienta exclusiva. Puede ejecutarse con cuaderno y observación. Para micronegocios es más crítico porque no pueden permitirse errores costosos." },
  { id: "N005", modulo: 1, tipoPregunta: "Afirmación-Razón", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un consultor sostiene que en La Dorada el mapeo de mercado es innecesario PORQUE los negocios pequeños ya se conocen entre sí.", pregunta: "Analice la relación lógica de causa-efecto entre la afirmación y la razón presentadas:", opciones: ["La afirmación es falsa; la razón es parcialmente válida porque la observación aporta algo, pero el mapeo es indispensable.", "Ambas verdaderas; la razón explica la afirmación porque en mercados pequeños basta la observación cotidiana.", "Ambas verdaderas; la razón no explica la afirmación porque el mapeo formal aporta información cuantificable que la observación no genera.", "Ambas falsas; el mapeo nunca aporta información útil a pequeños comercios."], correcta: 0, justificacion: "Aunque los comerciantes se conocen, el mapeo formal genera datos sistematizados (actores, márgenes, competidores) que la mera observación no produce." },
  { id: "N006", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.1", contexto: "Un analista afirma: 'El mapeo de mercado es una etapa previa y descartable del proceso estratégico, una vez hecho se archiva'.", pregunta: "Frente a la situación expuesta en el caso, ¿cuál es la evaluación estratégica más precisa?", opciones: ["Es correcto: una vez hecho, el mapeo se archiva y no se vuelve a usar.", "Es incorrecto: el mapeo es la base sobre la que se construyen decisiones estratégicas y se actualiza periódicamente.", "Es correcto: solo se usa al inicio del proyecto y luego se olvida.", "Es irrelevante para negocios pequeños."], correcta: 1, justificacion: "El mapeo no es descartable: es el diagnóstico estructural que fundamenta el resto de decisiones y se actualiza cuando el mercado cambia." },
  { id: "N007", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.1", contexto: "Un tendero afirma: 'Yo ya sé quiénes son mis clientes y competidores, no necesito mapear nada'. Después de dos años sus ventas caen sostenidamente sin entender por qué.", pregunta: "¿Qué sesgo cognitivo refleja esta postura?", opciones: ["Efecto halo: una característica positiva contamina toda su percepción.", "Efecto dotación: sobrevalora lo que ya tiene.", "Sesgo de confirmación: solo valora la información que confirma su creencia previa.", "Aversión a la pérdida: teme perder clientes."], correcta: 2, justificacion: "El sesgo de confirmación hace que el tendero busque y valore solo la información que confirma su creencia previa ('ya conozco mi mercado'), ignorando cambios reales del entorno." },
  { id: "N008", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.1", contexto: "Una asesora propone a dos micronegocios de La Dorada hacer un mapeo. El primero tiene $0 de presupuesto, el segundo tiene $500.000. Ambos quieren saber quién compite con ellos.", pregunta: "¿Qué opción es la más adecuada para AMBOS casos?", opciones: ["Contratar una consultora profesional, sin importar el presupuesto.", "Esperar a tener presupuesto para hacer el mapeo formal.", "Renunciar al mapeo porque no hay recursos suficientes.", "Realizar el mapeo con cuaderno y observación directa, ajustando profundidad según recursos disponibles."], correcta: 3, justificacion: "El mapeo es metodología adaptable. Puede ejecutarse con cuaderno y observación (Vía Limitada) o con herramientas digitales gratuitas (Vía Normal). El rigor no depende del presupuesto." },
  { id: "N009", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.1", contexto: "Un nuevo microempresario abre una tienda de abarrotes en La Dorada. Antes de definir qué vender, cuánto cobrar y a quién, necesita una herramienta estratégica base.", pregunta: "¿Cuál acción es la más adecuada para iniciar el negocio?", opciones: ["Realizar un mapeo del mercado local antes de definir oferta, precio y público.", "Definir los precios según lo que cobra la cadena nacional.", "Copiar el surtido de la tienda más exitosa del barrio.", "Lanzar una promoción agresiva el primer mes para atraer clientes."], correcta: 0, justificacion: "El mapeo de mercado es la base: identifica actores, competidores, precios y oportunidades reales antes de invertir en surtido, precio o promoción." },
  { id: "N010", modulo: 1, tipoPregunta: "Exclusión de Elementos", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista enumera los componentes que debe incluir un mapeo de mercado completo para un cliente de La Dorada.", pregunta: "¿Cuál de los siguientes NO forma parte del mapeo de mercado?", opciones: ["Identificación de actores: productores, intermediarios, consumidores.", "Proyección de estados financieros de la empresa a 5 años.", "Análisis de canales por los que llega el producto al cliente.", "Identificación de oportunidades no explotadas por el mercado actual."], correcta: 1, justificacion: "La proyección financiera es análisis contable, no parte del mapeo de mercado. El mapeo describe actores, canales, competencia y oportunidades." },
  { id: "N011", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe analizar por qué las ventas de un puesto de comidas rápidas cerca del terminal de La Dorada caen los martes y miércoles.", pregunta: "¿Cuál herramienta del mapeo resulta más adecuada para un primer diagnóstico?", opciones: ["Análisis PESTEL del sector gastronómico nacional.", "Mapa de canales de distribución de alimentos procesados.", "Mapa del comportamiento temporal del cliente flotante por franja horaria.", "Cadena de valor del sector agroindustrial del Magdalena Centro."], correcta: 2, justificacion: "El patrón temporal es un fenómeno de comportamiento del cliente flotante. La herramienta adecuada es el mapa de flujos del cliente por franja horaria." },
  { id: "N012", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "La finca lechera 'La Esperanza' vende a un acopiador a $1.100/litro. El acopiador vende a planta a $1.900; la planta al distribuidor a $2.800; el distribuidor al tender a $3.400; el consumidor final paga entre $3.900 y $4.300.", pregunta: "¿Qué herramienta del mapeo explica mejor la baja captura de valor del productor?", opciones: ["El análisis PESTEL del sector lácteo nacional.", "El mapa de competidores directos del productor.", "El análisis de las cinco fuerzas de Porter del sector lechero.", "La cadena de valor, que muestra el margen capturado por cada eslabón."], correcta: 3, justificacion: "La cadena de valor identifica cada eslabón desde la producción hasta el consumo y cuantifica cuánto margen captura cada actor. El productor captura ~26 % del precio final." },
  { id: "N013", modulo: 1, tipoPregunta: "Ordenamiento Secuencial", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Una estudiante construye la cadena de valor de la leche desde la finca hasta el consumidor final en La Dorada para analizar dónde se concentra el margen.", pregunta: "¿Cuál es el orden correcto de los eslabones de la cadena?", opciones: ["Finca → acopiador → planta → distribuidor → tender → consumidor final.", "Consumidor → tender → distribuidor → planta → acopiador → finca.", "Finca → distribuidor → planta → acopiador → consumidor final → tender.", "Consumidor final → planta → acopiador → finca → distribuidor → tender."], correcta: 0, justificacion: "El orden natural es: productor primario (finca), acopio intermedio, procesamiento (planta), distribución mayorista, retail minorista y consumidor final." },
  { id: "N014", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe aplicar las 5 Fuerzas de Porter a una pescadería de La Dorada. Identifica que existen otras 4 pescaderías y apps nacionales de domicilio.", pregunta: "¿Cuál pregunta corresponde a la fuerza 'amenaza de sustitutos'?", opciones: ["¿Cuántas pescaderías abrirán este año en el municipio?", "¿Qué productos alternativos puede elegir el cliente para cubrir la misma necesidad de proteína?", "¿Cuánto poder de negociación tienen los pescadores que proveen la materia prima?", "¿Qué tan fácil es para un nuevo competidor abrir una pescadería?"], correcta: 1, justificacion: "La amenaza de sustitutos mide productos alternativos que satisfacen la misma necesidad con otro bien (pollo, carne, huevos para la proteína)." },
  { id: "N015", modulo: 1, tipoPregunta: "Afirmación-Razón", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista sostiene que la cadena de valor es especialmente útil para negocios con muchos intermediarios PORQUE permite identificar quién captura el margen en cada eslabón.", pregunta: "Analice la relación lógica de causa-efecto entre la afirmación y la razón presentadas:", opciones: ["Ambas verdaderas pero la razón no se relaciona con la utilidad de la herramienta.", "La afirmación es verdadera; la razón es falsa.", "Ambas verdaderas y la razón explica correctamente la afirmación.", "Ambas falsas; la cadena de valor no aplica a negocios con intermediarios."], correcta: 2, justificacion: "La cadena de valor es especialmente útil cuando hay múltiples intermediarios porque permite visualizar la distribución del margen entre eslabones." },
  { id: "N016", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Una consultora debe mapear el mercado de motos de bajo cilindraje en La Dorada. Detecta tres tipos de usuarios: domiciliarios, trabajadores y jóvenes recreativos.", pregunta: "¿Cuál herramienta del mapeo permite diferenciar mejor estos tres usos?", opciones: ["Análisis PESTEL del sector transporte.", "Cadena de valor del ensamblaje de motocicletas.", "Mapa de canales de distribución del concesionario.", "Mapa de segmentación conductual por ocasión de uso."], correcta: 3, justificacion: "La segmentación conductual por ocasión de uso distingue consumidores por cómo usan el producto (domicilios, trabajo, recreación)." },
  { id: "N017", modulo: 1, tipoPregunta: "Exclusión de Elementos", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista construye el mapa de actores de un mercado de pescado fresco en La Dorada. Enumera los actores identificados en el terreno.", pregunta: "¿Cuál de los siguientes NO es un actor del mercado según la metodología de mapeo?", opciones: ["El clima promedio de la región durante la temporada.", "Los pescadores de la ribera que proveen la materia prima.", "El Invima que regula las condiciones sanitarias.", "Los compradores finales que adquieren el producto."], correcta: 0, justificacion: "El clima es un factor del entorno (PESTEL - Ecológico) pero no un actor del mercado. Los actores son individuos u organizaciones que participan en el intercambio." },
  { id: "N018", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista aplica PESTEL al sector pesquero de La Dorada. Encuentra: (a) requisitos sanitarios más estrictos; (b) inflación del 18 %; (c) auge de pedidos por WhatsApp; (d) nueva ley de protección de datos.", pregunta: "¿Cuál hallazgo corresponde al factor Tecnológico del PESTEL?", opciones: ["Hallazgo (a), porque los requisitos sanitarios modernizan al sector.", "Hallazgo (c), porque el desplazamiento hacia WhatsApp refleja cambio en hábitos digitales.", "Hallazgo (b), porque la inflación refleja el nivel tecnológico de la economía.", "Hallazgo (d), porque toda ley moderna es un avance tecnológico."], correcta: 1, justificacion: "El factor Tecnológico agrupa cambios en herramientas y hábitos digitales: adopción de canales, apps, comercio electrónico." },
  { id: "N019", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.2", contexto: "Un consultor debe elegir la herramienta más adecuada para diagnosticar por qué un negocio pierde clientes que antes compraban recurrentemente.", pregunta: "¿Cuál herramienta del mapeo es más pertinente para este objetivo?", opciones: ["Análisis PESTEL del sector comercial nacional.", "Cadena de valor del sector retail colombiano.", "Mapa de flujos del cliente que identifica puntos de abandono.", "Análisis de las 5 fuerzas de Porter del sector."], correcta: 2, justificacion: "El mapa de flujos del cliente (customer journey) permite identificar dónde abandona el consumidor y por qué. Es la herramienta directa para diagnosticar pérdida de clientes." },
  { id: "N020", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista desea mapear todos los competidores sustitutos de una tienda de gaseosas en un barrio de La Dorada.", pregunta: "¿Cuál opción incluye correctamente sustitutos del producto?", opciones: ["Otras tiendas que venden la misma marca de gaseosa.", "Panaderías y pastelerías del sector.", "Ferreterías y papelerías vecinas.", "Jugos naturales, aguas saborizadas, limonadas y bebidas energizantes."], correcta: 3, justificacion: "Los sustitutos son productos que satisfacen la misma necesidad (hidratación, sabor) con otro tipo de bien: jugos, aguas, limonadas, energizantes." },
  { id: "N021", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista construye el mapa de competidores de una panadería en La Dorada. Considera 4 ejes posibles: precio, calidad percibida, cercanía y variedad.", pregunta: "¿Cuál decisión metodológica es más rigurosa?", opciones: ["Elegir 2 ejes relevantes al problema estratégico y justificar la elección.", "Ubicar los competidores usando los 4 ejes simultáneamente en un solo gráfico.", "Usar solo el eje de precio porque es el más objetivo.", "Evitar el mapa y basarse en la observación directa del dueño."], correcta: 0, justificacion: "Un mapa de posicionamiento requiere 2 ejes claros y relevantes al problema. Usar 4 ejes simultáneos es inoperable; usar solo precio reduce la complejidad real." },
  { id: "N022", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista construye el mapa de canales de un negocio de arepas que vende en tienda física, por WhatsApp y por un intermediario en la plaza de mercado.", pregunta: "¿Cuál es el propósito principal de este mapa?", opciones: ["Identificar al dueño del negocio.", "Identificar por dónde llega el producto al cliente final y detectar canales subutilizados o costosos.", "Contar la cantidad de empleados.", "Medir el nivel de satisfacción del cliente."], correcta: 1, justificacion: "El mapa de canales identifica las rutas por las que el producto llega al cliente, permitiendo optimizar canales y detectar oportunidades." },
  { id: "N023", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista aplica las 5 fuerzas de Porter a una panadería del centro de La Dorada y analiza específicamente la rivalidad entre competidores existentes.", pregunta: "¿Cuál pregunta corresponde a esta fuerza?", opciones: ["¿Qué tan fácil es abrir una panadería nueva?", "¿Qué poder tienen los proveedores de harina?", "¿Cuántos competidores directos hay en el sector y qué tan intensa es su competencia?", "¿Qué productos alternativos puede comprar el cliente?"], correcta: 2, justificacion: "La rivalidad entre competidores existentes mide intensidad de competencia entre los jugadores actuales: número, tamaño, agresividad competitiva." },
  { id: "N024", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista construye el mapa de actores de un mercado de pescado. Identifica 6 actores: pescadores, transportadores, plaza, restaurantes, Invima y consumidor final.", pregunta: "¿Cuál de estos actores es un regulador?", opciones: ["Pescadores.", "Transportadores.", "Consumidor final.", "Invima."], correcta: 3, justificacion: "El Invima es la autoridad sanitaria reguladora del sector alimentario. Su rol es normar y vigilar el cumplimiento de estándares." },
  { id: "N025", modulo: 1, tipoPregunta: "Completación de Enunciado", nivel: "Aplicación", rap: "RAP 1.2", contexto: "En el análisis PESTEL, el factor __________ agrupa cambios en hábitos digitales y adopción de canales por parte del consumidor, mientras que el factor __________ agrupa la normatividad y regulaciones aplicables al sector.", pregunta: "¿Cuál opción completa correctamente ambos espacios?", opciones: ["Tecnológico / Legal.", "Político / Social.", "Económico / Ecológico.", "Social / Político."], correcta: 0, justificacion: "El factor Tecnológico agrupa herramientas y hábitos digitales. El factor Legal agrupa leyes y normativas aplicables." },
  { id: "N026", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista mapea el sector de bicicletas de La Dorada. Encuentra 3 tiendas, 2 talleres y un vendedor informal. Detecta que ningún negocio ofrece financiación o planes de pago.", pregunta: "¿Cómo se clasifica este hallazgo en el mapeo?", opciones: ["Como competidor directo identificado.", "Como oportunidad comercial no explotada en el mercado actual.", "Como amenaza regulatoria del sector.", "Como barrera tecnológica del mercado local."], correcta: 1, justificacion: "La ausencia de un servicio (financiación) que el cliente podría valorar es una oportunidad comercial no explotada, uno de los hallazgos típicos del mapeo." },
  { id: "N027", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe elegir entre 6 herramientas del mapeo para diagnosticar la caída de ventas de una tienda de barrio que compite con una cadena nacional recién llegada al sector.", pregunta: "¿Cuál herramienta es más pertinente para este caso específico?", opciones: ["Análisis PESTEL nacional.", "Cadena de valor del retail colombiano.", "Mapa de competidores con dos ejes (precio vs servicio).", "Análisis histórico de series de ventas."], correcta: 2, justificacion: "El conflicto es competitivo y local: una cadena recién llegada. El mapa de competidores con dos ejes (precio vs servicio) permite posicionar a ambos actores y detectar espacio estratégico." },
  { id: "N028", modulo: 1, tipoPregunta: "Exclusión de Elementos", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista enumera herramientas del mapeo para un cliente local antes de decidir cuál usar.", pregunta: "¿Cuál de las siguientes NO es una herramienta clásica del mapeo de mercado?", opciones: ["Mapa de actores.", "Cadena de valor.", "Análisis PESTEL.", "Estudio de tiempos y movimientos."], correcta: 3, justificacion: "El estudio de tiempos y movimientos es una herramienta de ingeniería industrial, no de mapeo de mercado. El mapeo usa actores, cadena de valor, PESTEL, Porter y canales." },
  { id: "N029", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe comparar dos mercados potenciales para que su cliente abra una segunda sucursal en La Dorada: el barrio Las Ferias y el centro de la ciudad.", pregunta: "¿Cuál herramienta del mapeo es más útil para esta comparación?", opciones: ["Mapa de competidores y flujos de clientes por zona.", "Cadena de valor del producto del cliente.", "Mapa de actores de cada zona.", "Análisis PESTEL regional."], correcta: 0, justificacion: "Comparar zonas requiere analizar cuántos competidores hay en cada una y cómo fluyen los clientes en cada zona. El mapa de competidores + flujos es la herramienta directa." },
  { id: "N030", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista aplica PESTEL al sector gastronómico de La Dorada. Detecta que la alcaldía implementará nuevas normas de manejo de residuos para restaurantes.", pregunta: "¿A qué factor del PESTEL corresponde este hallazgo?", opciones: ["Político.", "Ecológico y Legal (doble impacto).", "Económico.", "Tecnológico."], correcta: 1, justificacion: "La norma de manejo de residuos tiene doble componente: Legal (norma aplicable) y Ecológico (impacto ambiental). Ambos factores del PESTEL aplican." },
  { id: "N031", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Doña Martha tiene tienda de abarrotes en el barrio Las Ferias. Perdió 40 % de domicilios frente a una cadena nacional a 6 cuadras. Su margen es similar al de la cadena y se distingue por atención personalizada y entrega en 15 min.", pregunta: "¿Cuál decisión estratégica es más pertinente según el mapeo?", opciones: ["Reducir precios hasta igualar a la cadena aun perdiendo margen.", "Replicar el surtido de la cadena nacional aunque no se ajuste al barrio.", "Reorientar la comunicación hacia rapidez de domicilio y trato cercano como diferenciadores.", "Cerrar el negocio y buscar otro giro comercial más rentable."], correcta: 2, justificacion: "Cuando el mapeo revela ventajas competitivas reales (rapidez + trato personalizado), la estrategia óptima es reposicionar el negocio sobre esas ventajas en lugar de competir donde el rival es superior." },
  { id: "N032", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un consultor mapea el sector de comidas rápidas en el centro de La Dorada. Encuentra 12 negocios formales, 8 informales y una app nacional de domicilios. El dueño de un local quiere saber dónde está la oportunidad.", pregunta: "¿Cuál factor debe analizarse primero para detectar la oportunidad real?", opciones: ["El precio del alquiler de locales en el sector.", "La cantidad total de establecimientos formales e informales.", "El clima laboral de los empleados del sector gastronómico.", "Los segmentos de consumo desatendidos en horarios específicos y canales digitales."], correcta: 3, justificacion: "La oportunidad está en segmentos o necesidades desatendidas, no en el conteo bruto de competidores. El mapeo busca vacíos de oferta." },
  { id: "N033", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "El Hotel Mirador del Magdalena tiene ocupación alta entre semana (viajeros de negocios) pero cae al 25 % los fines de semana. El mapeo revela que ningún competidor ofrece paquetes de fin de semana que integren hotel + atractivos locales.", pregunta: "¿Qué conclusión es más coherente con el mapeo?", opciones: ["Diseñar paquetes de fin de semana que integren hotel + experiencias locales, aprovechando un segmento desatendido.", "Bajar precios el fin de semana para igualar a los hostales.", "Cerrar el hotel los fines de semana para reducir costos.", "Comprar los hostales competidores para eliminar la competencia."], correcta: 0, justificacion: "El mapeo revela un segmento desatendido (paquetes de experiencia). La oportunidad no está en competencia frontal por precio sino en crear una categoría nueva." },
  { id: "N034", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Una tienda de electrodomésticos en el centro de La Dorada vendía bien hasta 2018. Hoy perdió 40 % de ventas frente a marketplaces nacionales. El dueño dice: 'aquí la gente no compra por internet'.", pregunta: "¿Qué acción inmediata recomienda el principio del mapeo de mercado?", opciones: ["Invertir en pauta radial para reforzar el canal tradicional.", "Confirmar con un mapeo del consumidor local el porcentaje real que ya compra digitalmente antes de descartar el canal.", "Aumentar el inventario de productos con mayor margen.", "Reducir el horario de atención para bajar costos operativos."], correcta: 1, justificacion: "Antes de descartar un canal, el mapeo cuantifica la realidad del consumidor local. La afirmación del dueño es una suposición no verificada." },
  { id: "N035", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Una pescadería en La Dorada descubre que sus principales competidores no son las otras pescaderías sino los supermercados que venden pollo y las apps de domicilio.", pregunta: "¿Cómo se clasifican esos competidores?", opciones: ["Competidores directos.", "Aliados estratégicos.", "Competidores sustitutos.", "Proveedores indirectos."], correcta: 2, justificacion: "Los competidores sustitutos son productos que satisfacen la misma necesidad (proteína) pero con otro tipo de bien. Pollo y apps compiten por el mismo presupuesto." },
  { id: "N036", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Una tienda de abarrotes nota que los días de mayor venta son viernes y sábado, mientras los martes y miércoles son flojos. El dueño quiere entender esta variación.", pregunta: "¿Cuál herramienta del mapeo ayuda a entender esta variación?", opciones: ["Análisis PESTEL del sector retail nacional.", "Análisis de cadena de valor del sector alimentario.", "Análisis de las 5 fuerzas de Porter del barrio.", "Mapa del comportamiento temporal del cliente por día de la semana."], correcta: 3, justificacion: "El patrón temporal de ventas se mapea mediante el mapa de flujo del cliente por día. Es la herramienta adecuada para este análisis operativo." },
  { id: "N037", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un dueño de tienda en La Dorada afirma que 'su mercado es todo el barrio' y rechaza segmentar. Su tienda está en una zona con familias jóvenes, adultos mayores y estudiantes.", pregunta: "¿Qué pérdida estratégica genera esta postura?", opciones: ["Pierde la capacidad de adaptar oferta, precio y comunicación a las necesidades específicas de cada grupo del barrio.", "Ahorra costos al no segmentar, lo cual es positivo para el negocio.", "Aumenta la eficiencia al no dispersar recursos en múltiples segmentos.", "Reduce la complejidad operativa y mejora la rentabilidad."], correcta: 0, justificacion: "Rechazar la segmentación impide adaptar la oferta a cada grupo. Aunque simplifica la operación, pierde oportunidades de mayor rentabilidad por segmento." },
  { id: "N038", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un cliente quiere abrir una segunda sucursal. Antes de decidir, contrata un mapeo del mercado en la zona objetivo. El estudio debe identificar si vale la pena la expansión.", pregunta: "¿Qué hallazgo justificaría más sólidamente abrir la sucursal?", opciones: ["Alta concentración de competidores directos con oferta similar.", "Presencia de un segmento desatendido con capacidad de pago y sin oferta cercana.", "Bajos precios de alquiler sin análisis de demanda.", "Cercanía a la primera sucursal."], correcta: 1, justificacion: "El hallazgo que justifica la expansión es la existencia de un segmento desatendido con demanda real y capacidad de pago. Los otros hallazgos no sostienen la decisión por sí solos." },
  { id: "N039", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un dueño de tienda en La Dorada va a copiar exactamente la estrategia de una cadena nacional competidora para recuperar clientes. Un consultor le recomienda repensar.", pregunta: "¿Cuál es la recomendación más adecuada desde el mapeo?", opciones: ["Copiar la estrategia es la mejor opción porque el competidor es exitoso.", "Cerrar el negocio porque no puede competir con una cadena.", "Analizar primero las ventajas diferenciales locales (cercanía, trato, rapidez) y diseñar estrategia en función de ellas.", "Ignorar al competidor y seguir igual."], correcta: 2, justificacion: "El mapeo identifica ventajas diferenciales del cliente. Copiar al competidor exitoso desaprovecha los activos propios y deja al negocio en desventaja." },
  { id: "N040", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un negocio de comidas rápidas cerca del terminal tiene ticket promedio de $8.500 y clientes con 10–15 min para comprar. El dueño quiere subir el ticket implementando un menú extenso con 30 opciones.", pregunta: "Según el mapeo del comportamiento del cliente, ¿qué decisión es más adecuada?", opciones: ["Implementar el menú extenso porque más opciones generan más venta.", "Abrir una sucursal en el centro para atraer clientes locales.", "Ocultar los precios para fomentar la interacción con el personal.", "Rediseñar la oferta con combos rápidos de una mano y precios visibles desde lejos."], correcta: 3, justificacion: "El cliente flotante con 10 min valora rapidez y conveniencia, no variedad extensa. La oferta debe adaptarse al tiempo real del cliente." },
  { id: "N041", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de comidas rápidas del barrio. Descubre que todos los negocios cierran a las 8 p.m. y los jóvenes del sector estudian o trabajan hasta las 9 p.m.", pregunta: "En el marco del mapeo de mercado y análisis del entorno, ¿cómo se clasifica técnicamente este hallazgo?", opciones: ["Oportunidad comercial no explotada (horario desatendido).", "Competidor directo en un horario específico.", "Amenaza regulatoria del sector gastronómico.", "Barrera tecnológica del mercado local."], correcta: 0, justificacion: "Un horario desatendido con demanda potencial es una oportunidad comercial no explotada, hallazgo típico de un mapeo." },
  { id: "N042", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Una marca de arepas descubre que su principal competidor no es otra marca de arepas, sino la tortilla de maíz que venden en los supermercados a mitad de precio.", pregunta: "¿Cómo se clasifica este competidor?", opciones: ["Competidor directo.", "Competidor sustituto.", "Aliado estratégico.", "Proveedor indirecto."], correcta: 1, justificacion: "La tortilla satisface la misma necesidad (acompañamiento de comida) con otro producto. Es un competidor sustituto por presupuesto de acompañamiento." },
  { id: "N043", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un dueño de tienda de barrio descubre en su mapeo que el 60 % de sus clientes son amas de casa de 40+ años, pero no sabe si eso es bueno o malo para crecer.", pregunta: "¿Cuál es la lectura estratégica más precisa?", opciones: ["Es malo: solo crecerá si cambia a público joven.", "Es indiferente: el público no importa para el crecimiento.", "Es una base sólida que puede mantenerse, pero puede explorar segmentos adyacentes sin abandonar la base.", "Debe reemplazar a los clientes actuales con nuevos segmentos."], correcta: 2, justificacion: "Una base sólida de clientes leales es un activo. La estrategia correcta es mantenerla y explorar segmentos adyacentes (hijos que compran para sus padres, nuevos residentes del barrio) sin desmontar la base." },
  { id: "N044", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un mapeo del sector turístico de La Dorada revela que la mayoría de visitantes son viajeros de paso (Bogotá-Costa) y muy pocos son turistas que pernoctan más de una noche.", pregunta: "¿Cuál oportunidad surge del hallazgo?", opciones: ["Eliminar la oferta actual para viajeros de paso.", "Bajar precios para atraer más viajeros de paso.", "Copiar la estrategia de otros municipios.", "Crear experiencias que incentiven la pernoctación (rutas, paquetes, atractivos locales)."], correcta: 3, justificacion: "Si el mercado actual es de paso, la oportunidad está en transformar ese tránsito en estadía mediante experiencias que justifiquen quedarse más tiempo." },
  { id: "N045", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de frutas en La Dorada. Detecta que los supermercados venden fruta importada, mientras las plazas venden fruta local sin marca ni empaque.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Crear una marca local de fruta con empaque e identidad que compita por el consumidor que valora lo local.", "Reemplazar la fruta local por importada.", "Bajar precios de la fruta local hasta igualar a la importada.", "Abandonar el mercado de frutas por su baja rentabilidad."], correcta: 0, justificacion: "El mapeo revela un segmento mal atendido: consumidores que valoran producto local pero no encuentran presentación diferenciada. La marca local es la oportunidad." },
  { id: "N046", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista debe elegir la recomendación más sólida para un cliente cuya principal debilidad es no tener presencia digital, aunque su producto es de alta calidad y tiene clientes leales.", pregunta: "¿Cuál recomendación es la más estratégica?", opciones: ["Cerrar el negocio por falta de presencia digital.", "Activar WhatsApp Business con catálogo y validar digitalización básica antes de inversiones mayores.", "Invertir todo el presupuesto en pauta de Instagram.", "Copiar la estrategia digital de una cadena nacional."], correcta: 1, justificacion: "Para un negocio con producto sólido y sin digitalización, el paso correcto es activar canales digitales básicos y gratuitos (WhatsApp Business), validar demanda y luego escalar." },
  { id: "N047", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de servicios del hogar en La Dorada (plomería, electricidad, aseo). Detecta que la mayoría de prestadores trabajan sin contrato, sin factura y sin redes activas.", pregunta: "¿Qué oportunidad comercial se identifica?", opciones: ["Regresar al modelo informal para competir.", "Bajar precios por debajo de los informales.", "Formalizar el servicio con factura, contrato básico y presencia digital para diferenciarse.", "Esperar a que el mercado se formalice solo."], correcta: 2, justificacion: "La formalización (factura, contrato, presencia digital) es una oportunidad de diferenciación en un sector predominantemente informal. Genera confianza y acceso a clientes que valoran respaldo." },
  { id: "N048", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista identifica dos oportunidades: (a) bajar precios para recuperar clientes perdidos frente a una cadena; (b) fortalecer el servicio personalizado y la entrega rápida como diferencial.", pregunta: "¿Cuál de las dos rutas es estratégicamente superior y por qué?", opciones: ["Opción (a): bajar precios siempre es la solución más eficaz.", "Ambas son equivalentes en impacto estratégico.", "Ninguna de las dos es viable para un micronegocio.", "Opción (b): diferenciarse en servicio es más sostenible que competir por precio contra un rival con mayor escala."], correcta: 3, justificacion: "Competir por precio contra un rival con mayor escala destruye margen. La diferenciación en servicio (trato, rapidez, cercanía) es sostenible porque no puede ser replicada por la cadena." },
  { id: "N049", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de panaderías de La Dorada. Detecta que ninguna panadería local ofrece productos sin gluten ni opciones para diabéticos, y que el 12 % de los clientes potenciales declara alguna restricción alimentaria.", pregunta: "En el marco del mapeo de mercado y análisis del entorno, ¿cómo se clasifica técnicamente este hallazgo?", opciones: ["Como oportunidad de segmento desatendido con demanda comprobable.", "Como competidor directo.", "Como amenaza regulatoria.", "Como debilidad operativa."], correcta: 0, justificacion: "Un segmento con restricción alimentaria y oferta nula es una oportunidad de segmento desatendido, respaldada por el 12 % de demanda declarada." },
  { id: "N050", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista debe recomendar a un cliente si conviene invertir en publicidad pagada o primero mejorar la experiencia de compra física. El cliente tiene local en buen estado pero servicio lento y quejas recurrentes.", pregunta: "¿Cuál es la recomendación más estratégica?", opciones: ["Invertir toda la inversión en publicidad para atraer más gente.", "Mejorar primero la experiencia de compra (servicio, tiempos) antes de invertir en publicidad.", "Invertir mitad en publicidad y mitad en remodelación del local.", "No invertir en nada hasta que las ventas suban solas."], correcta: 1, justificacion: "Invertir en publicidad con servicio deficiente genera clientes que no vuelven. Mejorar la experiencia primero asegura que la inversión publicitaria tenga retorno." },
  { id: "N051", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Una finca lechera de La Dorada vende toda su producción a un único acopiador que le fija el precio. El productor quiere entender por qué su margen es tan bajo.", pregunta: "¿Qué herramienta del mapeo explica mejor su situación?", opciones: ["Análisis PESTEL regional.", "Mapa de competidores directos entre fincas.", "Cadena de valor desde la finca hasta el consumidor final.", "Análisis de las 5 fuerzas de Porter del sector lácteo."], correcta: 2, justificacion: "La cadena de valor cuantifica cuánto captura cada eslabón. El productor puede ver que el acopiador, la planta y el distribuidor capturan la mayor parte del precio final." },
  { id: "N052", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de gaseosas en un barrio. Descubre que la tienda del sector vende gaseosa pero también jugos naturales, aguas saborizadas y limonadas. Los clientes alternan entre las opciones según el clima y el momento.", pregunta: "¿Cómo se clasifican los jugos, aguas y limonadas respecto a la gaseosa?", opciones: ["Competidores directos.", "Aliados de la gaseosa.", "Complementos del negocio.", "Competidores sustitutos."], correcta: 3, justificacion: "Los sustitutos compiten por el mismo presupuesto de bebida con productos alternativos. Su presencia reduce la dependencia del cliente respecto a la gaseosa." },
  { id: "N053", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de peluquerías de La Dorada. Detecta que las peluquerías tradicionales atienden principalmente a adultos mayores, mientras los jóvenes prefieren cortarse en casa o en barberías nuevas que cobran más pero ofrecen ambiente temático.", pregunta: "¿Qué lectura estratégica es más precisa?", opciones: ["Las peluquerías tradicionales están perdiendo al segmento joven.", "El mercado joven no existe en La Dorada.", "Los adultos mayores son el único segmento viable.", "Las barberías nuevas no son competencia real."], correcta: 0, justificacion: "El mapeo revela que el segmento joven migró a un formato distinto (barberías temáticas). Las peluquerías tradicionales deben decidir si adaptan su propuesta o se concentran en su segmento actual." },
  { id: "N054", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de útiles escolares en La Dorada. Detecta que la mayoría de papelerías cierran a las 6 p.m. y que los estudiantes compran después de las 6 p.m., muchas veces en tiendas de barrio que no son papelerías especializadas.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Abrir una papelería nueva en el mismo horario que las existentes.", "Extender el horario de atención hasta más tarde para capturar al segmento estudiantil.", "Vender solo a estudiantes en horario escolar.", "Reducir el surtido de útiles para bajar costos."], correcta: 1, justificacion: "El desajuste entre horario de cierre y momento de compra es una oportunidad directa. Extender horario captura al segmento que hoy compra en tiendas no especializadas." },
  { id: "N055", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista identifica en el mapeo que un cliente tiene dos competidores directos, un sustituto fuerte (app nacional) y una cadena informal (vendedores ambulantes) que captura clientes por precio y cercanía.", pregunta: "¿Cuál es el mayor riesgo según el mapeo?", opciones: ["Los competidores directos.", "El sustituto digital por sí solo.", "La cadena informal de vendedores ambulantes porque combina precio y cercanía.", "Los empleados del negocio."], correcta: 2, justificacion: "La competencia informal con precio bajo y cercanía ataca dos atributos centrales del cliente. Es el competidor más peligroso en el contexto del mapeo." },
  { id: "N056", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de cafeterías de La Dorada. Detecta que la mayoría están ubicadas en el centro, mientras que en la zona del terminal no hay ninguna que atienda a los viajeros en espera.", pregunta: "¿Qué conclusión estratégica es más precisa?", opciones: ["El centro es la única ubicación viable para cafeterías.", "Cerrar las cafeterías del centro para migrar al terminal.", "Copiar la estrategia de las cafeterías del centro.", "La zona del terminal es una ubicación potencial desatendida para capturar al viajero."], correcta: 3, justificacion: "Un vacío de oferta en una ubicación con flujo de clientes (terminal) es una oportunidad de ubicación. El mapeo revela dónde está la demanda no atendida." },
  { id: "N057", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de servicios de aseo doméstico en La Dorada. Detecta que las amas de casa contratan informalmente con personas de su círculo, sin verificación de antecedentes ni respaldo formal.", pregunta: "¿Qué oportunidad detecta el mapeo?", opciones: ["Formalizar el servicio con verificación de antecedentes y respaldo.", "Competir bajando precios contra el servicio informal.", "Ofrecer el mismo servicio sin diferenciación.", "Esperar a que el mercado formalice por sí solo."], correcta: 0, justificacion: "La ausencia de formalización (verificación de antecedentes, respaldo) es una necesidad no cubierta que el cliente valoraría si existiera. Es una oportunidad de diferenciación." },
  { id: "N058", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de tiendas de mascotas en La Dorada. Detecta que la oferta se concentra en alimento y accesorios, pero ningún negocio ofrece servicios de baño y peluquería canina.", pregunta: "En el marco del mapeo de mercado y análisis del entorno, ¿cómo se clasifica técnicamente este hallazgo?", opciones: ["Como amenaza competitiva.", "Como oportunidad de servicio desatendido en el mercado.", "Como barrera regulatoria.", "Como debilidad operativa del cliente."], correcta: 1, justificacion: "Un servicio complementario sin oferta local es una oportunidad de ampliar la propuesta de valor y capturar mayor gasto por cliente." },
  { id: "N059", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista mapea el sector gastronómico de La Dorada. Detecta que la mayoría de restaurantes ofrecen el mismo menú (corriente, a la carta) y que ningún negocio ofrece opciones rápidas para ejecutivos con 30 minutos de almuerzo.", pregunta: "¿Cuál es la oportunidad más clara?", opciones: ["Abrir otro restaurante con el mismo menú.", "Bajar precios para capturar más clientes.", "Diseñar una oferta de menú ejecutivo rápido (30 min) para el segmento laboral.", "Vender solo a domicilio sin menú ejecutivo."], correcta: 2, justificacion: "El mapeo revela un segmento desatendido (ejecutivos con tiempo limitado). Una oferta específica de menú rápido captura ese segmento sin competir frontalmente." },
  { id: "N060", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de hoteles de La Dorada. Detecta que los hoteles del centro atienden a viajeros de negocios, mientras que los alojamientos cerca del río no aprovechan el atractivo turístico natural de la ribera.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Cerrar los hoteles del centro.", "Bajar precios en todos los hoteles.", "Ignorar la ribera y concentrarse en el centro.", "Diseñar experiencias turísticas en la ribera que aprovechen el atractivo natural."], correcta: 3, justificacion: "El mapeo revela un activo natural no explotado. Diseñar experiencias alrededor de la ribera captura un segmento turístico distinto al de negocios." },
  { id: "N061", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de moda en La Dorada. Detecta que los almacenes venden ropa genérica pero ninguno ofrece servicio de personalización (arreglos, tallas especiales, diseño local).", pregunta: "En el marco del mapeo de mercado y análisis del entorno, ¿cómo se clasifica técnicamente este hallazgo?", opciones: ["Como oportunidad de diferenciación por servicio personalizado.", "Como amenaza de nuevos entrantes.", "Como debilidad operativa.", "Como barrera de entrada."], correcta: 0, justificacion: "La personalización es una necesidad no cubierta que puede diferenciar a un negocio en un mercado homogéneo. Es una oportunidad de captura de valor." },
  { id: "N062", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista evalúa dos escenarios para un cliente con presupuesto limitado: (a) invertir todo en una campaña de radio; (b) dividir el presupuesto en WhatsApp Business + mejoras de punto de venta + cupones de fidelización.", pregunta: "¿Cuál es la recomendación más estratégica?", opciones: ["Opción (a): la radio tiene mayor alcance masivo.", "Opción (b): diversificar acciones de bajo costo permite probar varios canales con el mismo presupuesto.", "Ambas son iguales en retorno.", "Ninguna es viable para el cliente."], correcta: 1, justificacion: "Con presupuesto limitado, diversificar en acciones de bajo costo permite experimentar canales, medir resultados y ajustar. La radio masiva consume todo sin capacidad de iteración." },
  { id: "N063", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de servicios de reparación de celulares en La Dorada. Detecta que la mayoría de los negocios no ofrecen garantía formal ni repuestos certificados.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Bajar precios para competir con los informales.", "Copiar el modelo informal para bajar costos.", "Ofrecer garantía formal y repuestos certificados como diferenciador de confianza.", "No hacer nada; el mercado está bien así."], correcta: 2, justificacion: "Ofrecer garantía y repuestos certificados genera confianza en un sector con desconfianza generalizada. Es un diferenciador sostenible." },
  { id: "N064", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de talleres de motos de La Dorada. Detecta que los domiciliarios (que usan la moto 8 horas diarias) hacen mantenimiento reactivo cuando se daña, no preventivo.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Vender más motos a los domiciliarios.", "Cerrar el taller para evitar problemas.", "Esperar a que los domiciliarios cambien su comportamiento solos.", "Ofrecer planes de mantenimiento preventivo por kilometraje para domiciliarios."], correcta: 3, justificacion: "Los planes preventivos por kilometraje atienden la necesidad real del domiciliario (evitar paros) y generan ingresos recurrentes al taller." },
  { id: "N065", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de servicios odontológicos en La Dorada. Detecta que la mayoría de consultorios no ofrecen atención los sábados, mientras que los trabajadores (segmento mayoritario) solo pueden ir los sábados.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Extender el horario a los sábados para atender al segmento laboral.", "Abrir el consultorio solo los sábados.", "Mantener el mismo horario de lunes a viernes.", "Ofrecer servicios solo a jubilados."], correcta: 0, justificacion: "El desajuste entre disponibilidad del cliente y horario del servicio es una oportunidad. Ajustar el horario captura al segmento trabajador sin perder el de semana." },
  { id: "N066", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de servicios de contabilidad en La Dorada. Detecta que la mayoría de contadores atienden a empresas medianas y grandes, y los microempresarios quedan sin asesoría formal.", pregunta: "En el marco del mapeo de mercado y análisis del entorno, ¿cómo se clasifica técnicamente este hallazgo?", opciones: ["Como amenaza competitiva.", "Como oportunidad de segmento desatendido (microempresarios).", "Como barrera regulatoria.", "Como debilidad del contador."], correcta: 1, justificacion: "Un segmento grande sin oferta formal es una oportunidad. Los microempresarios requieren asesoría adaptada y accesible que los contadores tradicionales no ofrecen." },
  { id: "N067", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de guarderías infantiles de La Dorada. Detecta que ninguna ofrece horario extendido hasta las 8 p.m., cuando madres y padres salen del trabajo.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Abrir otra guardería con el mismo horario.", "Cerrar las guarderías actuales.", "Ofrecer horario extendido hasta 8 p.m. para madres trabajadoras.", "Abrir solo los sábados."], correcta: 2, justificacion: "El desajuste entre cierre de guardería y fin de jornada laboral es una oportunidad directa. Extender el horario captura al segmento que hoy busca soluciones alternativas." },
  { id: "N068", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de ferreterías de La Dorada. Detecta que las ferreterías del centro atienden a maestros de obra, pero los pequeños arreglos del hogar son atendidos por tiendas que no son especializadas.", pregunta: "¿Cuál es la oportunidad más clara?", opciones: ["Cerrar las ferreterías del centro.", "Bajar precios a todos los productos.", "Vender solo al por mayor.", "Diseñar una línea específica para pequeños arreglos del hogar (kit básico, asesoría)."], correcta: 3, justificacion: "Un segmento (hogar) mal atendido por ferreterías especializadas en obra es una oportunidad. Kits específicos + asesoría capturan un mercado desatendido." },
  { id: "N069", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de panaderías. Detecta que todas ofrecen productos tradicionales pero ninguna ofrece opciones saludables (integrales, sin azúcar, veganas) que demanda el segmento joven-adulto.", pregunta: "¿Cuál es la oportunidad más clara?", opciones: ["Incorporar línea de productos saludables para capturar segmento joven-adulto.", "Ofrecer más productos tradicionales.", "Reducir agresivamente los precios de venta sin ajustar la estructura de costos operativos.", "Cerrar la panadería por falta de demanda."], correcta: 0, justificacion: "Un segmento (joven-adulto) con preferencia por salud tiene demanda declarada pero oferta nula. Incorporar una línea específica captura ese mercado sin perder el actual." },
  { id: "N070", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista debe priorizar entre tres oportunidades detectadas para un cliente: (a) atender el segmento joven digital; (b) mejorar la experiencia del cliente actual; (c) expandir la oferta a un nuevo producto.", pregunta: "¿Cuál es la más estratégica como punto de partida?", opciones: ["(a) Ir directo a captar el segmento joven digital.", "(b) Mejorar la experiencia del cliente actual, porque asegura la base antes de expandir.", "(c) Expandir la oferta porque siempre hay que innovar.", "Las tres por igual."], correcta: 1, justificacion: "Antes de expandir a nuevos segmentos o productos, asegurar la base actual es prioritario. Un cliente satisfecho es la plataforma para cualquier crecimiento posterior." },
  { id: "N071", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe construir el mapa de un mercado donde la mayoría de productos pasa por 4 intermediarios antes de llegar al consumidor.", pregunta: "¿Qué herramienta es más útil para visualizar este flujo?", opciones: ["Análisis PESTEL.", "Mapa de competidores.", "Cadena de valor con márgenes por eslabón.", "Análisis de redes sociales."], correcta: 2, justificacion: "La cadena de valor es la herramienta que visualiza cada eslabón y cuantifica el margen capturado por cada actor. Ideal para cadenas largas con intermediarios." },
  { id: "N072", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista aplica PESTEL al sector de turismo en La Dorada. Encuentra: (a) nueva normativa de seguridad turística; (b) alza del dólar que encarece viajes internacionales; (c) nuevas generaciones que prefieren turismo de experiencia; (d) auge de plataformas digitales de reserva.", pregunta: "¿Cuál hallazgo corresponde al factor Social del PESTEL?", opciones: ["Hallazgo (a).", "Hallazgo (b).", "Hallazgo (d).", "Hallazgo (c)."], correcta: 3, justificacion: "El factor Social agrupa cambios en preferencias culturales, valores y estilos de vida. La preferencia por turismo de experiencia es un cambio social, no económico ni legal." },
  { id: "N073", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista identifica en su mapeo que la panadería del cliente compite con 4 panaderías del sector, pero también con 2 cafeterías que venden pan y con una tienda de sándwiches a domicilio.", pregunta: "¿Cómo se clasifican las cafeterías y la tienda de sándwiches?", opciones: ["Competidores sustitutos.", "Competidores directos.", "Proveedores.", "Aliados."], correcta: 0, justificacion: "Cafeterías y tienda de sándwiches ofrecen productos alternativos que sustituyen el consumo de pan en ciertos momentos del día. Son competidores sustitutos." },
  { id: "N074", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista construye el mapa de competidores de una tienda de ropa en La Dorada. Detecta: (a) dos tiendas de ropa del centro; (b) una tienda de ropa en Instagram; (c) un marketplace nacional con envío a domicilio; (d) un vecino que vende ropa usada.", pregunta: "¿Cuál de estos competidores opera en un canal completamente distinto?", opciones: ["(a) Las tiendas del centro.", "(c) El marketplace nacional con envío.", "(b) La tienda de ropa en Instagram.", "(d) El vecino con ropa usada."], correcta: 1, justificacion: "El marketplace nacional opera en un canal digital de escala nacional, con dinámicas distintas al comercio local. Es un competidor de otro canal, no solo de otra tienda física." },
  { id: "N075", modulo: 1, tipoPregunta: "Reconocimiento de Sesgos", nivel: "Evaluación", rap: "RAP 1.2", contexto: "Un analista debe recomendar la herramienta más adecuada para un cliente que quiere entender POR QUÉ su público objetivo no lo elige, sabiendo que ya identificó a los competidores.", pregunta: "¿Cuál herramienta es más pertinente?", opciones: ["Mapa de competidores con 2 ejes.", "Análisis PESTEL.", "Mapa del customer journey con puntos de decisión y abandono.", "Cadena de valor."], correcta: 2, justificacion: "Si ya conoce los competidores pero no entiende el por qué del rechazo, la herramienta adecuada es el mapa del journey que revela dónde y por qué abandona el cliente." },
  { id: "N076", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe decidir si clasifica el contenido de un estudio como PESTEL o como 5 Fuerzas de Porter.", pregunta: "¿Cuál es el criterio de distinción más preciso?", opciones: ["Son sinónimos y cualquier clasificación es válida.", "Porter analiza el entorno macro; PESTEL la competencia.", "Ambos analizan lo mismo con distinto nombre.", "PESTEL analiza el entorno externo macro; Porter analiza la intensidad competitiva del sector."], correcta: 3, justificacion: "PESTEL analiza factores externos (políticos, económicos, sociales, tecnológicos, ecológicos, legales) del entorno. Porter mide intensidad competitiva (rivalidad, entrantes, sustitutos, poder de proveedores y compradores)." },
  { id: "N077", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe analizar el entorno legal que afecta a un cliente del sector alimentario. Detecta regulaciones sanitarias, impuestos y normativa laboral.", pregunta: "¿Cuál de estos elementos NO corresponde al factor Legal del PESTEL?", opciones: ["Nivel de inflación interanual del país.", "Regulaciones sanitarias aplicables al sector.", "Normativa de protección de datos personales.", "Impuestos municipales aplicables al negocio."], correcta: 0, justificacion: "La inflación es un factor Económico del PESTEL, no Legal. Los demás son normativos y corresponden al factor Legal." },
  { id: "N078", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista detecta en su mapeo que un cliente tiene alta rivalidad (muchas tiendas similares), bajo poder de negociación con proveedores y alta amenaza de sustitutos.", pregunta: "¿Qué herramienta del mapeo está usando?", opciones: ["Análisis PESTEL.", "Análisis de las 5 Fuerzas de Porter.", "Cadena de valor.", "Mapa de canales."], correcta: 1, justificacion: "La descripción (rivalidad, poder de proveedores, sustitutos) son 3 de las 5 fuerzas de Porter. El análisis está directamente aplicando este modelo." },
  { id: "N079", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe analizar el poder de negociación de los compradores en un mercado donde hay pocos clientes grandes y muchos proveedores pequeños.", pregunta: "¿Cuál es la lectura correcta desde las 5 Fuerzas de Porter?", opciones: ["El poder de compradores es bajo.", "El poder de compradores no aplica en este caso.", "El poder de compradores es alto porque concentran la demanda.", "El poder de compradores y proveedores es equivalente."], correcta: 2, justificacion: "Cuando hay pocos compradores grandes y muchos proveedores pequeños, los compradores tienen alto poder de negociación porque pueden dictar condiciones." },
  { id: "N080", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista clasifica los actores de un mercado de pescado así: pescadores (proveedores), transportadores (logística), plaza (canal), consumidores (demandantes) e Invima (regulador).", pregunta: "¿Cuál es el propósito principal de esta clasificación?", opciones: ["Definir precios de venta.", "Elegir colores para el logo del cliente.", "Calcular impuestos aplicables.", "Comprender los roles y la estructura del mercado para diseñar estrategias diferenciadas."], correcta: 3, justificacion: "Clasificar actores por rol permite entender la estructura del mercado: quién oferta, quién demanda, quién regula y quién intermedia. Es la base para estrategias diferenciadas." },
  { id: "N081", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista detecta que su cliente puede atender tres segmentos: estudiantes, amas de casa y oficinistas. Los recursos del cliente son limitados para el mes.", pregunta: "¿Cuál criterio debe usar para priorizar el segmento?", opciones: ["El segmento con mayor atractivo y mayor viabilidad de ser atendido con los recursos actuales.", "El segmento con mayor tamaño absoluto.", "El segmento de mayor edad.", "El segmento de mayor margen por unidad sin considerar volumen."], correcta: 0, justificacion: "La priorización combina atractivo (rentabilidad potencial) y capacidad (posibilidad real de atenderlo con los recursos actuales)." },
  { id: "N082", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista compara dos barrios para que su cliente abra una segunda sucursal. El barrio A tiene 3 tiendas similares. El barrio B no tiene ninguna tienda similar, pero tampoco tiene infraestructura vial adecuada.", pregunta: "¿Cuál es la lectura correcta del mapeo?", opciones: ["Barrio A es mejor porque tiene más movimiento comercial.", "Ambos tienen señales mixtas: A tiene competencia pero infraestructura; B tiene vacío pero limitaciones operativas.", "Barrio B es mejor porque no hay competencia directa.", "Ninguno es viable."], correcta: 1, justificacion: "El mapeo completo exige evaluar múltiples factores. A tiene competencia (desventaja) pero infraestructura (ventaja). B tiene vacío (ventaja) pero mala infraestructura (desventaja). Ninguno es concluyente sin análisis combinado." },
  { id: "N083", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un cliente tiene dos opciones: (a) expandir a un barrio adyacente; (b) profundizar en el barrio actual con nuevos productos.", pregunta: "¿Qué información del mapeo justificaría la opción (a) sobre la (b)?", opciones: ["El barrio actual es mejor porque ya se conoce.", "Es indistinto, ambas opciones son equivalentes.", "El barrio actual tiene alta competencia y margen decreciente, mientras el barrio adyacente tiene segmento desatendido con capacidad de pago.", "La opción (a) siempre es mejor porque expande."], correcta: 2, justificacion: "El mapeo justifica expansión cuando el barrio actual está saturado y el adyacente tiene un segmento desatendido con demanda comprobable. Sin esa evidencia, la expansión es arriesgada." },
  { id: "N084", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el mercado de servicios de salud en La Dorada. Detecta que las farmacias del centro atienden consultas básicas, mientras los consultorios médicos formales están fuera del alcance económico de gran parte de la población.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Cerrar los consultorios formales.", "Ignorar la brecha y atender solo al segmento de mayores ingresos.", "Copiar el modelo formal sin ajustes.", "Ofrecer servicios básicos accesibles en las farmacias (consulta, control de presión, glucemia)."], correcta: 3, justificacion: "Una brecha de acceso con demanda real es una oportunidad. Las farmacias pueden ampliar servicios básicos para atender un segmento hoy desatendido por limitaciones económicas." },
  { id: "N085", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de transporte intermunicipal en La Dorada. Detecta que todos los transportadores atienden las mismas rutas y horarios, sin oferta para viajeros con equipaje grande o mascotas.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Diseñar un servicio específico para viajeros con equipaje grande o mascotas.", "Cerrar los transportadores actuales.", "Bajar precios a todos los tiquetes.", "Ofrecer el mismo servicio sin diferenciación."], correcta: 0, justificacion: "La ausencia de oferta para un segmento específico (equipaje, mascotas) es una oportunidad de diferenciación directa. Captura un segmento desatendido sin competir frontalmente." },
  { id: "N086", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de restaurantes de La Dorada. Detecta que la mayoría ofrecen platos similares pero ninguno tiene opciones infantiles adaptadas (porciones pequeñas, sin condimentos fuertes) para familias con niños.", pregunta: "En el marco del mapeo de mercado y análisis del entorno, ¿cómo se clasifica técnicamente este hallazgo?", opciones: ["Competidor directo.", "Oportunidad de segmento desatendido.", "Amenaza regulatoria.", "Barrera tecnológica."], correcta: 1, justificacion: "Un segmento (familias con niños) con necesidades específicas y oferta nula es una oportunidad desatendida que puede capturarse con menús adaptados." },
  { id: "N087", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un cliente del sector gastronómico tiene dos opciones: (a) bajar precios para competir con la cadena de bajo costo; (b) especializarse en un tipo de cocina con identidad local.", pregunta: "¿Cuál opción es estratégicamente superior?", opciones: ["(a) Bajar precios porque siempre atrae más clientes.", "Ambas son equivalentes.", "(b) Especializarse con identidad local porque genera diferenciación sostenible.", "Ninguna es viable."], correcta: 2, justificacion: "Bajar precios frente a una cadena de bajo costo destruye margen y compite en el terreno donde el rival es superior. La especialización con identidad local crea diferenciación sostenible." },
  { id: "N088", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de telecomunicaciones locales. Detecta que el servicio de internet en las veredas es deficiente y que la mayoría de los operadores grandes no invierten allí por baja rentabilidad aparente.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Ignorar las veredas por baja rentabilidad.", "Copiar la estrategia de los operadores grandes.", "Reducir agresivamente los precios de venta sin ajustar la estructura de costos operativos.", "Ofrecer un servicio de internet satelital o comunitario adaptado al contexto rural."], correcta: 3, justificacion: "Un segmento desatendido por los grandes operadores es una oportunidad para soluciones adaptadas (satelital, comunitario, alianzas). La ausencia de oferta es la señal clave." },
  { id: "N089", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.3", contexto: "Un analista detecta que un cliente tiene ventaja en precio pero desventaja en calidad percibida, mientras un competidor directo tiene mejor calidad percibida pero precios más altos.", pregunta: "¿Cuál es la lectura estratégica más precisa?", opciones: ["El cliente debe mejorar la calidad percibida antes de competir por precio en el largo plazo.", "El cliente debe subir precios para igualar al competidor.", "El cliente debe bajar aún más los precios para ganar mercado.", "El cliente no tiene problema: el precio gana siempre."], correcta: 0, justificacion: "El precio bajo sin calidad percibida genera rotación pero no lealtad. Antes de profundizar la ventaja de precio, el cliente debe mejorar la calidad percibida para construir base sólida." },
  { id: "N090", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.3", contexto: "Un analista mapea el sector de colegios privados pequeños de La Dorada. Detecta que la mayoría compiten por precio, pero las familias valoran más la atención personalizada y la calidad educativa que el costo.", pregunta: "¿Cuál es la recomendación estratégica?", opciones: ["Bajar más los precios para atraer familias.", "Reforzar la propuesta en atención personalizada y calidad, alineándose con lo que valoran las familias.", "Copiar la estrategia de los colegios grandes.", "Mantener el rumbo actual sin ajustes."], correcta: 1, justificacion: "Cuando el mapeo revela que el cliente compite en un atributo (precio) que no es el que más valoran las familias, la estrategia correcta es alinearse con los atributos valorados." },
  { id: "N091", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.1", contexto: "Un analista pregunta a un cliente: '¿Qué necesita saber para tomar decisiones estratégicas el próximo trimestre?'. El cliente no puede responder.", pregunta: "¿Qué le falta al cliente según el principio del mapeo?", opciones: ["Invertir en publicidad.", "Contratar más empleados.", "Comprender el mercado en el que opera antes de definir estrategia.", "Comprar tecnología nueva."], correcta: 2, justificacion: "Si el cliente no puede responder qué necesita saber, es porque no ha mapeado su mercado. Sin diagnóstico del ecosistema no hay estrategia posible." },
  { id: "N092", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.1", contexto: "Un analista explica al dueño de un negocio que el mapeo de mercado es el paso previo a cualquier estrategia de marketing. El dueño pregunta por qué.", pregunta: "¿Cuál es la mejor explicación?", opciones: ["Porque el gobierno lo exige.", "Porque es más económico que otros análisis.", "Porque garantiza el éxito del negocio.", "Porque permite entender actores, competidores y oportunidades antes de invertir."], correcta: 3, justificacion: "El mapeo evita invertir en estrategias basadas en suposiciones. Al identificar actores, competidores y oportunidades, orienta la inversión con evidencia." },
  { id: "N093", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista pregunta a dos tenderos cuántos competidores directos tienen. El primero responde 'muchos'. El segundo responde 'tres específicos: A, B y C, con estos precios'.", pregunta: "¿Cuál de los dos tenderos demuestra comprensión del mapeo?", opciones: ["El segundo, porque identifica competidores específicos con datos concretos.", "El primero, porque reconoce que hay muchos.", "Asumir que ambas posturas presentan el mismo nivel de rigor técnico en el mapeo.", "Ninguno; el mapeo no requiere identificar competidores específicos."], correcta: 0, justificacion: "El mapeo exige identificar competidores específicos con datos verificables, no impresiones vagas. El segundo tendero demuestra comprensión real." },
  { id: "N094", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista debe decidir si un negocio requiere mapeo completo o solo investigación específica de mercado.", pregunta: "¿Cuál es el criterio de decisión más preciso?", opciones: ["Si el negocio es grande, mapeo; si es pequeño, investigación.", "Si el negocio desconoce la estructura de su mercado, mapeo; si ya la conoce y quiere profundizar un aspecto, investigación.", "Ambas herramientas son indistintas.", "El criterio es el presupuesto disponible."], correcta: 1, justificacion: "El criterio es el estado de conocimiento del mercado, no el tamaño del negocio. Si desconoce la estructura, necesita mapeo. Si ya la conoce, investigación específica." },
  { id: "N095", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.1", contexto: "Un cliente le dice a un analista: 'Solo quiero saber si mi precio es competitivo'. El analista sospecha que el problema real es más amplio.", pregunta: "¿Qué debería hacer el analista primero?", opciones: ["Responder directamente con precios de la competencia.", "Ignorar la pregunta y hacer un análisis financiero.", "Realizar un mapeo del mercado para entender la estructura antes de responder la pregunta específica.", "Recomendar bajar precios."], correcta: 2, justificacion: "El mapeo previo permite verificar si el problema real es el precio o algo más. Responder sin contexto puede llevar a decisiones equivocadas." },
  { id: "N096", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista debe explicar a un cliente por qué el mapeo tiene valor incluso si el negocio está bien y vende bien.", pregunta: "¿Cuál es la mejor explicación?", opciones: ["El mapeo no aporta nada si el negocio está bien.", "El mapeo solo sirve para negocios en crisis.", "El mapeo es un requisito legal.", "El mapeo permite anticipar cambios en el mercado, detectar riesgos futuros y descubrir oportunidades adyacentes."], correcta: 3, justificacion: "El mapeo no es solo para crisis; también permite anticipar cambios, identificar riesgos futuros y detectar oportunidades adyacentes antes de que la competencia las vea." },
  { id: "N097", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista describe el mapeo como 'dibujar el terreno antes de jugar'. Un cliente pregunta si el símil aplica también a negocios que llevan 20 años operando.", pregunta: "¿Cuál es la respuesta correcta?", opciones: ["Aplica especialmente, porque los mercados cambian y el conocimiento previo puede volverse obsoleto.", "No aplica porque ya conocen el terreno.", "Solo aplica a negocios nuevos.", "Es indiferente."], correcta: 0, justificacion: "Los negocios veteranos son los más propensos a operar con mapas mentales obsoletos. El mapeo actualizado es especialmente valioso para ellos." },
  { id: "N098", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.1", contexto: "Un analista lista cinco beneficios del mapeo para un cliente: (1) ver competidores reales; (2) entender la cadena; (3) detectar oportunidades; (4) anticipar tendencias; (5) mejorar precios.", pregunta: "¿Cuál de los cinco NO es un beneficio típico del mapeo?", opciones: ["Ver competidores reales.", "Mejorar precios automáticamente.", "Entender la cadena de valor.", "Detectar oportunidades."], correcta: 1, justificacion: "El mapeo no mejora precios automáticamente. Identifica estructura y oportunidades, pero las decisiones de precio requieren análisis complementario." },
  { id: "N099", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista y un cliente debaten si el mapeo debe hacerlo el dueño del negocio o un externo.", pregunta: "¿Cuál es la postura más sólida?", opciones: ["Solo un externo puede hacerlo bien.", "Solo el dueño puede hacerlo bien.", "El dueño conoce su negocio pero puede tener sesgos; un externo aporta mirada neutral. Ambos aportan.", "Ninguno; el mapeo requiere software especializado."], correcta: 2, justificacion: "El dueño conoce el negocio pero puede tener sesgos de confirmación. Un externo aporta mirada neutral. La combinación suele ser más sólida que cualquiera por separado." },
  { id: "N100", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.1", contexto: "Un analista debe decidir si el mapeo debe hacerse ANTES o DESPUÉS de definir el modelo de negocio.", pregunta: "¿Cuál es el orden más adecuado?", opciones: ["Después, para verificar lo que ya se decidió.", "Simultáneamente, no importa el orden.", "El orden depende del presupuesto.", "Antes, para que el modelo de negocio se diseñe con evidencia del mercado."], correcta: 3, justificacion: "El mapeo va antes: informa la definición del modelo de negocio con datos reales del mercado. Hacerlo después convierte el mapeo en validación, no en base." },
  { id: "N101", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un cliente pregunta a un analista cuánto tiempo toma un mapeo de mercado para un micronegocio.", pregunta: "¿Cuál es la respuesta más honesta?", opciones: ["Puede tomar de 1 a 4 semanas para un micronegocio con recursos mínimos, dependiendo de la profundidad y los recursos.", "Siempre toma al menos 6 meses.", "Toma exactamente 3 meses independiente del caso.", "No hay forma de estimarlo."], correcta: 0, justificacion: "El mapeo es escalable. Para un micronegocio puede ser rápido (1-4 semanas), con observación directa y análisis del entorno. La profundidad y recursos determinan el tiempo." },
  { id: "N102", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Evaluación", rap: "RAP 1.1", contexto: "Un analista debe priorizar qué componentes del mapeo hacer primero si el presupuesto solo cubre una parte del trabajo.", pregunta: "¿Cuál componente priorizar primero?", opciones: ["El análisis de tendencias futuras.", "La identificación de actores y competidores, porque es la base de todo lo demás.", "El análisis de redes sociales.", "La proyección financiera."], correcta: 1, justificacion: "Sin identificar actores y competidores no se puede hacer análisis PESTEL, cadena de valor ni estrategias. Es la base del mapeo." },
  { id: "N103", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.1", contexto: "Un analista pregunta a un cliente: 'Si tuviera que describir su mercado en una sola frase, ¿qué diría?'. El cliente responde: 'No lo he pensado'.", pregunta: "¿Desde la perspectiva del mapeo de mercado, qué diagnóstico describe mejor la situación de este comerciante?", opciones: ["Aplica un modelo ágil y empírico que prescinde intencionalmente del análisis formal del mercado.", "Controla eficientemente su entorno operativo al no delimitar su negocio a un segmento específico.", "Opera bajo intuición cotidiana sin una definición clara de su segmento ni de su propuesta de valor.", "Reduce sus costos operativos al descartar estudios de mercado en su toma de decisiones."], correcta: 2, justificacion: "La falta de definición del mercado evidencia una gestión puramente intuitiva y reactiva, impidiendo enfocar recursos comerciales y anticipar a los competidores locales." },
  { id: "N104", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe elegir la herramienta más adecuada para entender si un cliente puede sostener el margen frente a sus proveedores.", pregunta: "¿Cuál es más pertinente?", opciones: ["Mapa de actores.", "Cadena de valor.", "Análisis PESTEL.", "Análisis del poder de proveedores (Porter)."], correcta: 3, justificacion: "La fuerza de Porter 'poder de proveedores' mide específicamente la capacidad del cliente de negociar con sus proveedores, determinando si puede sostener margen." },
  { id: "N105", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe mapear cómo llegan los productos al cliente final en una tienda de abarrotes. Detecta: proveedores directos, distribuidores, mayoristas y vendedores informales.", pregunta: "¿Cuál herramienta permite visualizar mejor este flujo?", opciones: ["Mapa de canales de distribución.", "Cadena de valor con márgenes.", "Análisis PESTEL.", "Análisis de redes sociales."], correcta: 0, justificacion: "El mapa de canales de distribución identifica específicamente las rutas por las que el producto llega al cliente final, incluyendo todos los intermediarios del flujo." },
  { id: "N106", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista necesita entender cómo está distribuida la oferta geográficamente en el municipio de La Dorada.", pregunta: "¿Cuál herramienta es más adecuada?", opciones: ["Análisis PESTEL.", "Mapa de actores geográfico.", "Análisis de las 5 fuerzas de Porter.", "Cadena de valor."], correcta: 1, justificacion: "Un mapa de actores geográfico (o mapa de competidores por zona) permite visualizar dónde está concentrada la oferta en el municipio." },
  { id: "N107", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista identifica que una tienda de abarrotes tiene una relación muy estrecha con sus clientes habituales, a quienes conoce por nombre y preferencias.", pregunta: "¿Cómo se registra este hallazgo en el mapeo?", opciones: ["Como amenaza competitiva.", "Como barrera regulatoria.", "Como oportunidad de capital relacional para fidelización.", "Como debilidad operativa."], correcta: 2, justificacion: "La relación cercana con clientes es capital relacional, un activo diferenciador frente a competidores impersonales como cadenas." },
  { id: "N108", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe realizar un análisis del entorno macro para un cliente del sector alimentario antes de definir su estrategia.", pregunta: "¿Cuál herramienta es la más adecuada?", opciones: ["Cadena de valor.", "Mapa de actores.", "Análisis de competidores.", "PESTEL."], correcta: 3, justificacion: "PESTEL analiza sistemáticamente los factores externos macro (Políticos, Económicos, Sociales, Tecnológicos, Ecológicos, Legales) que afectan al sector." },
  { id: "N109", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista debe explicar la diferencia entre el mapa de competidores y el mapa de actores a un cliente que confunde ambos términos.", pregunta: "¿Cuál es la explicación más precisa?", opciones: ["El mapa de actores incluye a TODOS los participantes (proveedores, reguladores, intermediarios). El mapa de competidores solo ubica a los rivales por cliente.", "Son sinónimos.", "El mapa de competidores incluye a TODOS los actores del mercado.", "Ambos se centran solo en clientes."], correcta: 0, justificacion: "El mapa de actores es amplio: incluye a todos los participantes del mercado. El mapa de competidores se enfoca específicamente en quienes compiten por el mismo cliente." },
  { id: "N110", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe analizar el nivel de rivalidad que enfrenta un cliente comparado con el promedio del sector.", pregunta: "¿Cuál herramienta es más adecuada?", opciones: ["Análisis PESTEL.", "Análisis de las 5 Fuerzas de Porter (fuerza de rivalidad).", "Mapa de canales.", "Cadena de valor."], correcta: 1, justificacion: "La fuerza de rivalidad entre competidores existentes mide específicamente la intensidad competitiva del sector. Es una de las 5 Fuerzas de Porter." },
  { id: "N111", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe mapear los flujos de un mercado de servicios educativos complementarios (clases particulares) en La Dorada.", pregunta: "¿Cuál es la herramienta más específica?", opciones: ["Análisis PESTEL regional.", "Análisis de las 5 fuerzas de Porter.", "Cadena de valor del servicio (estudiante → necesidad → clases → resultados).", "Mapa de canales del retail."], correcta: 2, justificacion: "Para servicios, la cadena de valor describe el recorrido del servicio desde la necesidad hasta la entrega y resultado. Es la herramienta adecuada." },
  { id: "N112", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista debe mapear un mercado donde los actores cambian con frecuencia estacional (por ejemplo, vendedores de útiles escolares).", pregunta: "¿Qué consideración metodológica es más importante?", opciones: ["Ignorar la estacionalidad.", "Solo registrar actores permanentes.", "Solo registrar actores temporales.", "Documentar los actores por temporada para no confundir presencia temporal con permanencia."], correcta: 3, justificacion: "En mercados estacionales, el mapeo debe distinguir actores permanentes de temporales para no sobreestimar la competencia permanente ni subestimar la temporal." },
  { id: "N113", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe evaluar si su cliente puede entrar a un nuevo mercado sin competir frontalmente con los líderes actuales.", pregunta: "¿Cuál herramienta permite evaluar mejor las barreras de entrada?", opciones: ["Análisis de amenaza de nuevos entrantes (Porter).", "Cadena de valor.", "Análisis PESTEL.", "Mapa de canales."], correcta: 0, justificacion: "La fuerza 'amenaza de nuevos entrantes' mide específicamente las barreras de entrada: capital, regulación, economías de escala. Ideal para evaluar expansión." },
  { id: "N114", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista detecta que en La Dorada varios negocios compiten por el mismo proveedor limitado de un insumo clave (por ejemplo, pescado fresco).", pregunta: "¿Cómo se registra este hallazgo en Porter?", opciones: ["Alta rivalidad entre competidores.", "Alto poder de proveedores (por oferta limitada del insumo).", "Alta amenaza de sustitutos.", "Baja amenaza de nuevos entrantes."], correcta: 1, justificacion: "Cuando el insumo es limitado y varios competidores lo necesitan, el proveedor tiene poder de negociación alto, afectando márgenes y disponibilidad." },
  { id: "N115", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista detecta que la mayoría de clientes del mercado de servicios de salud en La Dorada son empleados con ingresos fijos, mientras la oferta es fragmentada.", pregunta: "¿Qué factor del mapeo es más relevante aquí?", opciones: ["La estacionalidad de la oferta.", "El clima del municipio.", "La concentración de la demanda (empleados formales).", "La regulación de precios."], correcta: 2, justificacion: "La concentración de la demanda en un segmento específico (empleados formales) es un hallazgo clave que orienta la oferta y el diseño de servicios." },
  { id: "N116", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe clasificar los siguientes hallazgos del mapeo: 'tres competidores directos', 'regulación sanitaria', 'auge de pedidos digitales', 'preferencia por producto local'.", pregunta: "¿Cuál de estos corresponde al factor Social del PESTEL?", opciones: ["Tres competidores directos.", "Regulación sanitaria.", "Auge de pedidos digitales.", "Preferencia por producto local."], correcta: 3, justificacion: "La preferencia por producto local es un cambio en valores y hábitos culturales del consumidor, factor Social del PESTEL." },
  { id: "N117", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe clasificar los siguientes hallazgos: 'alza de aranceles', 'cambio de alcalde', 'conexión 5G en la región', 'campaña de reciclaje municipal'.", pregunta: "¿Cuál corresponde al factor Ecológico del PESTEL?", opciones: ["Campaña de reciclaje municipal.", "Alza de aranceles.", "Cambio de alcalde.", "Conexión 5G en la región."], correcta: 0, justificacion: "La campaña de reciclaje es un factor Ecológico, vinculado a sostenibilidad ambiental del entorno." },
  { id: "N118", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista identifica que un cliente tiene una relación muy estrecha con un solo proveedor, del cual depende para toda su operación.", pregunta: "¿Cuál es el riesgo según Porter?", opciones: ["Bajo riesgo: un proveedor simplifica la operación.", "Alto poder del proveedor: dependencia que limita márgenes y flexibilidad.", "Bajo poder del proveedor porque hay confianza.", "No aplica, Porter no evalúa proveedores."], correcta: 1, justificacion: "La dependencia de un solo proveedor eleva su poder de negociación y genera riesgo operativo. Es un hallazgo de alto poder de proveedores." },
  { id: "N119", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Análisis", rap: "RAP 1.2", contexto: "Un analista detecta que el mercado tiene muchos vendedores pequeños y ningún líder claro, generando competencia intensa por precio.", pregunta: "¿Cómo se registra este hallazgo?", opciones: ["Baja rivalidad.", "Bajo poder de proveedores.", "Alta rivalidad entre competidores por fragmentación del mercado.", "Alta amenaza de sustitutos."], correcta: 2, justificacion: "La fragmentación del mercado con muchos jugadores pequeños y sin líder genera alta rivalidad, especialmente por precio." },
  { id: "N120", modulo: 1, tipoPregunta: "Opción Múltiple", nivel: "Aplicación", rap: "RAP 1.2", contexto: "Un analista debe mapear el mercado de turismo de naturaleza en La Dorada y detecta: senderos, río, fauna y ausencia de operadores turísticos especializados.", pregunta: "A partir de los datos y el comportamiento del consumidor descritos, ¿qué oportunidad de mercado se identifica?", opciones: ["Cerrar los operadores existentes.", "Bajar precios a los paquetes existentes.", "Copiar el modelo de otros municipios.", "Diseñar productos turísticos de naturaleza aprovechando el activo natural sin explotar."], correcta: 3, justificacion: "El mapeo revela un activo (naturaleza) sin explotación comercial adecuada. Es una oportunidad de crear productos turísticos específicos." }
];
